// Associe chaque réponse de Claude à son post, filtre et construit le digest.
const SEUIL = 60;
const posts = $('Dédoublonner et préparer').all();
const reponses = $input.all();
const esc = s => String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const labels = { offre_emploi_directe: 'Offre directe', recherche_freelance: 'Mission freelance', besoin_implicite: 'Besoin implicite', recruteur_agence: 'Agence', autre: 'Autre' };

const qualifies = [], ecartes = [];
let erreurs = 0;
reponses.forEach((r, i) => {
  const post = (posts[i] && posts[i].json) || {};
  const msg = r.json || {};
  if (msg.error || msg.stop_reason === 'refusal') { erreurs++; return; }
  const bloc = (msg.content || []).find(b => b.type === 'text');
  let q;
  try { q = JSON.parse(bloc.text); } catch (e) { erreurs++; return; }
  const ligne = { ...post, ...q };
  (q.est_recrutement && q.score >= SEUIL ? qualifies : ecartes).push(ligne);
});
qualifies.sort((a, b) => b.score - a.score);

const date = new Date().toLocaleDateString('fr-CA', { timeZone: 'America/Toronto', weekday: 'long', day: 'numeric', month: 'long' });
const carte = p => `
  <div style="border:1px solid #ddd;border-radius:8px;padding:12px;margin:10px 0;">
    <div style="font-size:13px;color:#666;">Score <b>${p.score}</b> · ${esc(labels[p.type_signal] || p.type_signal)} · ${esc(p.persona_auteur)}${p.postedAgo ? ' · ' + esc(p.postedAgo) : ''}</div>
    <div style="font-weight:bold;margin:4px 0;">${esc(p.poste || 'Poste non précisé')}${p.entreprise ? ' · ' + esc(p.entreprise) : ''}${p.localisation ? ' · ' + esc(p.localisation) : ''}</div>
    <div style="font-size:13px;"><a href="${esc(p.authorUrl)}">${esc(p.author)}</a> · ${esc(p.headline)}</div>
    <p style="font-size:14px;margin:8px 0;"><b>Pourquoi :</b> ${esc(p.raison)}</p>
    <p style="font-size:14px;margin:8px 0;background:#f4f8ff;padding:8px;border-radius:6px;"><b>Angle :</b> ${esc(p.angle_approche)}</p>
    <p style="font-size:13px;color:#444;">${esc(p.text.slice(0, 280))}…</p>
    <a href="${esc(p.postUrl)}">Voir le post</a>
  </div>`;

const resume = `${reponses.length} nouveaux posts analysés par Claude · ${qualifies.length} retenus (score ≥ ${SEUIL})${erreurs ? ` · ${erreurs} en erreur` : ''}`;
const html = `<h2>Signaux Toronto, ${esc(date)}</h2><p>${resume}</p>` +
  (qualifies.length ? qualifies.map(carte).join('') : '<p>Aucun signal assez pertinent aujourd\'hui.</p>');

return [{ json: { count: qualifies.length, subject: `Signaux Toronto : ${qualifies.length} signaux qualifiés`, html } }];
